289	void CollectionImpl::prepare_schema() {
290	  // set default index params for vector fields
291	  for (auto &field : schema_->fields()) {
292	    if (field->is_vector_field()) {
293	      if (field->index_params() == nullptr) {
294	        field->set_index_params(DefaultVectorIndexParams);
295	      }
296	    }
297	  }
298	}
299	
300	CollectionImpl::CollectionImpl(const std::string &path) : path_(path) {}
301	
302	CollectionImpl::~CollectionImpl() {
303	  if (!destroyed_) {
304	    Close();
305	  }
306	}
307	
308	Status CollectionImpl::Open(const CollectionOptions &options) {
309	  options_ = options;
310	
311	  if (schema_ != nullptr && options_.read_only_) {
312	    return Status::InvalidArgument(
313	        "Unable to create collection with read-only mode.");
314	  }
315	
316	  Status s;
317	  if (schema_ == nullptr) {
318	    // recovery from disk
319	    s = recovery();
320	  } else {
321	    // create new collection with existing schema
322	    s = create();
323	  }
324	
325	  auto profiler = std::make_shared<Profiler>();
326	  sql_engine_ = sqlengine::SQLEngine::create(profiler);
327	
328	  return s;
329	}
330	
331	Status CollectionImpl::Close() {
332	  // only called in deconstructor
333	  std::lock_guard lock(schema_handle_mtx_);
334	
335	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
336	
337	  return close_unsafe();
338	}
339	
340	Status CollectionImpl::close_unsafe() {
341	  Status result = Status::OK();
342	
343	  // flush
344	  if (!options_.read_only_) {
345	    auto s = flush_unsafe();
346	    if (!s.ok()) {
347	      result = s;
348	    }
349	  }
350	
351	  // always release resources regardless of flush outcome
352	  writing_segment_.reset();
353	  segment_manager_.reset();
354	  version_manager_.reset();
355	  id_map_.reset();
356	  delete_store_.reset();
357	
358	  lock_file_.close();
359	
360	  return result;
361	}
362	
363	Status CollectionImpl::Destroy() {
364	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
365	
366	  std::lock_guard lock(schema_handle_mtx_);
367	
368	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
369	
370	  auto s = close_unsafe();
371	  CHECK_RETURN_STATUS(s);
372	
373	  ailego::FileHelper::RemoveDirectory(path_.c_str());
374	
375	  destroyed_ = true;
376	
377	  return Status::OK();
378	}
379	
380	Status CollectionImpl::Flush() {
381	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
382	
383	  std::lock_guard lock(schema_handle_mtx_);
384	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
385	
386	  return flush_unsafe();
387	}
388	
389	Status CollectionImpl::flush_unsafe() {
390	  if (!writing_segment_) {
391	    return Status::InternalError(
392	        "flush writing segment failed because writing segment is nullptr");
393	  }
394	  return writing_segment_->flush();
395	}
396	
397	Result<std::string> CollectionImpl::Path() const {
398	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
399	
400	  return path_;
401	}
402	
403	Result<CollectionStats> CollectionImpl::Stats() const {
404	  std::lock_guard lock(schema_handle_mtx_);
405	
406	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
407	
408	  auto segments = get_all_segments();
409	
410	  CollectionStats stats;
411	  auto vector_fields = schema_->vector_fields();
412	  if (segments.empty()) {
413	    stats.doc_count = 0;
414	    for (auto &field : vector_fields) {
415	      stats.index_completeness[field->name()] =
416	          1;  // if no doc, completeness is 1
417	    }
418	    return stats;
419	  }
