  Status s;
  if (schema_ == nullptr) {
    // recovery from disk
    s = recovery();
  } else {
    // create new collection with existing schema
    s = create();
  }

  auto profiler = std::make_shared<Profiler>();
  sql_engine_ = sqlengine::SQLEngine::create(profiler);

  return s;
