Status CollectionImpl::close_unsafe() {
  Status result = Status::OK();

  // flush
  if (!options_.read_only_) {
    auto s = flush_unsafe();
    if (!s.ok()) {
      result = s;
    }
  }

  // always release resources regardless of flush outcome
  writing_segment_.reset();
  segment_manager_.reset();
  version_manager_.reset();
  id_map_.reset();
  delete_store_.reset();

  lock_file_.close();

  return result;
}

