  CHECK_COLLECTION_READONLY_RETURN_STATUS;

  std::lock_guard lock(schema_handle_mtx_);

  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);

  auto s = close_unsafe();
  CHECK_RETURN_STATUS(s);

  ailego::FileHelper::RemoveDirectory(path_.c_str());

  destroyed_ = true;

  return Status::OK();
